use std::ffi::OsString;
use std::os::unix::ffi::OsStringExt;
use std::process::Command;

const BIN: &str = "/workspace/dataset/test4_executable";

fn run(args: &[Vec<u8>]) -> (i32, Vec<u8>, Vec<u8>) {
    let mut c = Command::new(BIN);
    for a in args { c.arg(OsString::from_vec(a.clone())); }
    let o = c.output().expect("spawn");
    (o.status.code().unwrap_or(-1), o.stdout, o.stderr)
}

struct R(u64);
impl R { fn n(&mut self)->u64{ self.0^=self.0<<13; self.0^=self.0>>7; self.0^=self.0<<17; self.0 } }

fn main() {
    let mut r = R(0x123456789abcdef);
    let mut checked = 0u64;
    let mut diffs = 0u64;
    // alphabet biased toward interesting bytes
    let alpha: Vec<u8> = (1u8..=255).collect();
    for _ in 0..4000 {
        // random argv[1]
        let len = (r.n() % 40) as usize;
        let mut a1 = Vec::new();
        for _ in 0..len {
            let x = (r.n() % 100) as usize;
            if x < 40 { a1.push(b"abcxyz01-._".to_vec()[(r.n()%11) as usize]); }
            else if x < 60 { a1.push(b'.'); }
            else { a1.push(alpha[(r.n() % 255) as usize]); }
        }
        let base = run(&[a1.clone()]);
        // random extras
        let ne = (r.n() % 6) as usize;
        let mut args = vec![a1.clone()];
        for _ in 0..ne {
            let el = (r.n() % 30) as usize;
            let mut e = Vec::new();
            for _ in 0..el { e.push(alpha[(r.n() % 255) as usize]); }
            args.push(e);
        }
        let got = run(&args);
        checked += 1;
        if base != got {
            diffs += 1;
            if diffs < 6 {
                println!("DIFF argv1={:?}\n  base rc={} out={:?} err={:?}\n  got  rc={} out={:?} err={:?}\n  extras={:?}",
                    a1, base.0, String::from_utf8_lossy(&base.1), String::from_utf8_lossy(&base.2),
                    got.0, String::from_utf8_lossy(&got.1), String::from_utf8_lossy(&got.2), &args[1..]);
            }
        }
        // sanity: stdout always exactly 8 bytes, stderr empty, rc 0
        if base.1.len()!=8 || !base.2.is_empty() || base.0!=0 {
            println!("SHAPE base argv1={:?} rc={} outlen={} err={:?}", a1, base.0, base.1.len(), String::from_utf8_lossy(&base.2));
        }
        if got.1.len()!=8 || !got.2.is_empty() || got.0!=0 {
            println!("SHAPE got argv1={:?} rc={} outlen={} err={:?}", a1, got.0, got.1.len(), String::from_utf8_lossy(&got.2));
        }
    }
    println!("fuzz checked={} diffs={}", checked, diffs);
}
